SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS `extract_artifact`;
CREATE TABLE `extract_artifact` (
  `id` int NOT NULL AUTO_INCREMENT,
  `run_file_id` bigint NOT NULL,
  `name` varchar(200) NOT NULL,
  `kind` varchar(20) NOT NULL,
  `mime` varchar(100) NOT NULL,
  `size_bytes` int NOT NULL,
  `sha256` char(64) NOT NULL,
  `content` longblob NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_artifact` (`run_file_id`,`name`),
  KEY `idx_artifact_sha` (`sha256`),
  CONSTRAINT `fk_art_rf` FOREIGN KEY (`run_file_id`) REFERENCES `extract_run_file` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
DROP TABLE IF EXISTS `extract_destination`;
CREATE TABLE `extract_destination` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '目的地 ID',
  `name` varchar(128) NOT NULL COMMENT '目的地名称（唯一）',
  `db_type` varchar(32) NOT NULL COMMENT '目标库类型：mysql 等',
  `conn_ref` varchar(128) NOT NULL COMMENT '凭据引用名（env 或 secrets.json，非密码）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间（UTC）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_dest_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='入库目的地：目标库连接引用（凭据引用制，密码不入库）';
DROP TABLE IF EXISTS `extract_load_log`;
CREATE TABLE `extract_load_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '入库回执 ID',
  `run_id` bigint NOT NULL COMMENT '所属运行 ID',
  `run_file_id` bigint NOT NULL COMMENT '所属运行文件 ID',
  `record_index` int NOT NULL COMMENT '记录序号',
  `destination_id` bigint NOT NULL COMMENT '目的地 ID',
  `target_table` varchar(128) NOT NULL COMMENT '目标业务表名',
  `target_pk` varchar(255) NOT NULL COMMENT '目标行主键值',
  `action` varchar(16) NOT NULL COMMENT '动作：insert/update/upsert/delete',
  `loaded_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '入库时间（UTC）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_load_receipt` (`run_file_id`,`record_index`,`destination_id`,`target_table`),
  KEY `fk_ll_run` (`run_id`),
  KEY `fk_ll_dest` (`destination_id`),
  CONSTRAINT `fk_ll_dest` FOREIGN KEY (`destination_id`) REFERENCES `extract_destination` (`id`),
  CONSTRAINT `fk_ll_rf` FOREIGN KEY (`run_file_id`) REFERENCES `extract_run_file` (`id`),
  CONSTRAINT `fk_ll_run` FOREIGN KEY (`run_id`) REFERENCES `extract_run` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='入库回执：每条记录写入目标库的幂等收据（唯一键防重）';
DROP TABLE IF EXISTS `extract_load_mapping`;
CREATE TABLE `extract_load_mapping` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '入库映射 ID',
  `destination_id` bigint NOT NULL COMMENT '目的地 ID',
  `template_id` bigint NOT NULL COMMENT '模板 ID',
  `target_table` varchar(128) NOT NULL COMMENT '目标业务表名',
  `column_map_json` json NOT NULL COMMENT '模板字段到目标列映射',
  `write_mode` varchar(16) NOT NULL DEFAULT 'upsert' COMMENT '写入模式：upsert/insert/update',
  `business_key_json` json DEFAULT NULL COMMENT '业务键（upsert 去重依据）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_dest_tpl_table` (`destination_id`,`template_id`,`target_table`),
  KEY `fk_lm_tpl` (`template_id`),
  CONSTRAINT `fk_lm_dest` FOREIGN KEY (`destination_id`) REFERENCES `extract_destination` (`id`),
  CONSTRAINT `fk_lm_tpl` FOREIGN KEY (`template_id`) REFERENCES `extract_template` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='入库映射：模板字段到目标表列的映射与写入策略';
DROP TABLE IF EXISTS `extract_quarantine`;
CREATE TABLE `extract_quarantine` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '隔离记录 ID',
  `run_id` bigint NOT NULL COMMENT '所属运行 ID',
  `run_file_id` bigint DEFAULT NULL COMMENT '所属运行文件 ID',
  `record_index` int DEFAULT NULL COMMENT '记录序号（records.json 内）',
  `stage` varchar(16) NOT NULL COMMENT '隔离阶段：extract/collect/review/load',
  `reason` text NOT NULL COMMENT '隔离原因',
  `payload_json` json NOT NULL COMMENT '问题记录快照',
  `state` varchar(16) NOT NULL DEFAULT 'open' COMMENT '处理状态：open/resolved/rejected',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '隔离时间（UTC）',
  `resolved_at` datetime DEFAULT NULL COMMENT '处理时间（UTC）',
  PRIMARY KEY (`id`),
  KEY `idx_q_run` (`run_id`,`state`),
  KEY `fk_q_rf` (`run_file_id`),
  CONSTRAINT `fk_q_rf` FOREIGN KEY (`run_file_id`) REFERENCES `extract_run_file` (`id`),
  CONSTRAINT `fk_q_run` FOREIGN KEY (`run_id`) REFERENCES `extract_run` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='隔离区：校验/入库失败记录，按 (run_file_id,record_index) 引用事实源';
DROP TABLE IF EXISTS `extract_run`;
CREATE TABLE `extract_run` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '运行 ID',
  `mode` varchar(16) NOT NULL COMMENT '模式：preview 预览 / load 入库',
  `template_version_id` bigint NOT NULL COMMENT '使用的模板版本 ID',
  `destination_id` bigint DEFAULT NULL COMMENT '入库目的地 ID（preview 为空）',
  `load_mapping_id` bigint DEFAULT NULL COMMENT '入库映射 ID（preview 为空）',
  `params_json` json DEFAULT NULL COMMENT '生效提取参数快照',
  `state` varchar(24) NOT NULL DEFAULT 'pending' COMMENT '运行状态：pending/extracting/previewed/loaded/failed/partial',
  `error` text COMMENT '错误信息（失败时）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '发起时间（UTC）',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间（UTC）',
  PRIMARY KEY (`id`),
  KEY `idx_run_state` (`state`),
  KEY `fk_run_tv` (`template_version_id`),
  KEY `fk_run_dest` (`destination_id`),
  KEY `fk_run_lm` (`load_mapping_id`),
  CONSTRAINT `fk_run_dest` FOREIGN KEY (`destination_id`) REFERENCES `extract_destination` (`id`),
  CONSTRAINT `fk_run_lm` FOREIGN KEY (`load_mapping_id`) REFERENCES `extract_load_mapping` (`id`),
  CONSTRAINT `fk_run_tv` FOREIGN KEY (`template_version_id`) REFERENCES `extract_template_version` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='运行批次：一次提取/入库的目录登记（内容事实源在 output/records.json）';
DROP TABLE IF EXISTS `extract_run_file`;
CREATE TABLE `extract_run_file` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '运行文件 ID',
  `run_id` bigint NOT NULL COMMENT '所属运行 ID',
  `source_file_id` bigint NOT NULL COMMENT '源文件 ID',
  `state` varchar(24) NOT NULL DEFAULT 'pending' COMMENT '文件状态：pending/extracting/previewed/loaded/failed',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_run_file` (`run_id`,`source_file_id`),
  KEY `fk_rf_file` (`source_file_id`)
) ENGINE=InnoDB AUTO_INCREMENT=29 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='运行文件：批次内每个源文件的处理状态与产物目录';
DROP TABLE IF EXISTS `extract_source_file`;
CREATE TABLE `extract_source_file` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '源文件 ID',
  `name` varchar(255) NOT NULL COMMENT '原始文件名',
  `sha256` char(64) NOT NULL COMMENT '内容 SHA-256（去重键）',
  `kind` varchar(16) NOT NULL COMMENT '载体类型：image/pdf/csv/text',
  `size_bytes` bigint NOT NULL COMMENT '文件字节数',
  `content` longblob NOT NULL,
  `tags` varchar(512) DEFAULT NULL COMMENT '标签（逗号分隔，可选）',
  `note` text COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '登记时间（UTC）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_source_sha` (`sha256`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='源文件目录：sha256 去重登记，规范副本存 sources/';
DROP TABLE IF EXISTS `extract_staging_field`;
CREATE TABLE `extract_staging_field` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `record_id` bigint NOT NULL,
  `field_name` varchar(128) NOT NULL COMMENT '模板字段名（动态）',
  `value_text` text NOT NULL COMMENT '当前值（含 edited）',
  `original_text` text NOT NULL COMMENT '提取原值',
  PRIMARY KEY (`id`),
  KEY `idx_field_value` (`field_name`,`value_text`(191)),
  KEY `idx_record` (`record_id`)
) ENGINE=InnoDB AUTO_INCREMENT=9808 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
DROP TABLE IF EXISTS `extract_staging_lineage`;
CREATE TABLE `extract_staging_lineage` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `record_id` bigint NOT NULL,
  `field_name` varchar(128) NOT NULL,
  `region_seq` int NOT NULL COMMENT '区域保序（同 cv_lineage 约定）',
  `page` int NOT NULL,
  `table_index` int DEFAULT NULL,
  `table_scope` varchar(16) DEFAULT NULL,
  `space` varchar(16) NOT NULL COMMENT 'source/rectified',
  `cell_bbox` varchar(128) DEFAULT NULL COMMENT '[x0,y0,x1,y1] json 字符串',
  `raw_text` text,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_rec_field_seq` (`record_id`,`field_name`,`region_seq`)
) ENGINE=InnoDB AUTO_INCREMENT=9808 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
DROP TABLE IF EXISTS `extract_staging_record`;
CREATE TABLE `extract_staging_record` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `run_file_id` bigint NOT NULL COMMENT '引用 extract_run_file.id',
  `record_index` int NOT NULL COMMENT '记录在文件内下标（引用键的一半）',
  `review_state` varchar(16) NOT NULL DEFAULT 'pending' COMMENT 'pending/edited/confirmed',
  `review_at` datetime DEFAULT NULL COMMENT '校验时间（UTC）',
  `values_json` mediumtext NOT NULL COMMENT '当前值全保真 body（API 重建用）',
  `original_json` mediumtext NOT NULL COMMENT '提取原值，永不覆盖',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_rf_idx` (`run_file_id`,`record_index`),
  KEY `idx_review` (`review_state`)
) ENGINE=InnoDB AUTO_INCREMENT=748 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
DROP TABLE IF EXISTS `extract_template`;
CREATE TABLE `extract_template` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '模板 ID',
  `name` varchar(128) NOT NULL COMMENT '模板名（唯一）',
  `description` varchar(512) DEFAULT NULL COMMENT '模板说明',
  `current_version` int NOT NULL DEFAULT '1' COMMENT '当前生效版本号',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间（UTC）',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间（UTC）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_template_name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='提取模板：目标字段定义/映射/转换的版本容器';
DROP TABLE IF EXISTS `extract_template_version`;
CREATE TABLE `extract_template_version` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '模板版本 ID',
  `template_id` bigint NOT NULL COMMENT '所属模板 ID',
  `version` int NOT NULL COMMENT '版本号（模板内递增）',
  `schema_json` json DEFAULT NULL COMMENT '目标字段定义（空=透传）',
  `mapping_json` json DEFAULT NULL COMMENT '源到目标字段映射（空=透传）',
  `transform_json` json DEFAULT NULL COMMENT '字段转换规则（空=透传）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间（UTC）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tpl_ver` (`template_id`,`version`),
  CONSTRAINT `fk_tv_template` FOREIGN KEY (`template_id`) REFERENCES `extract_template` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='模板版本：三段 JSON（字段定义/映射/转换）不可变快照';
DROP TABLE IF EXISTS `schema_version`;
CREATE TABLE `schema_version` (
  `version` int NOT NULL,
  `applied_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`version`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
SET FOREIGN_KEY_CHECKS=1;